107:     const str = (o, s) => { for (let i = 0; i < s.length; i++) v.setUint8(o + i, s.charCodeAt(i)); };
108:     str(0, 'RIFF');
109:     v.setUint32(4, 36 + total * 2, true);
110:     str(8, 'WAVE');
111:     str(12, 'fmt ');
112:     v.setUint32(16, 16, true);
113:     v.setUint16(20, 1, true);
114:     v.setUint16(22, 1, true);
