118:                 }));
119:             }
120:             catch (e) {
121:                 throw fail('uploading', e);
122:             }
123:         }
124:         mark('saving');
125:         const name = taskNameOf(text);
126:         const body = { name, created: Date.now(), items: [] };
127:         if (settings.model)
128:             body.model = settings.model;
129:         // effort всегда в body: иначе задача стартует без effort и модель рассуждает «как попало»
130:         body.effort = settings.effort || 'low';
131:         // Запуск агента — как всегда, триггером on_save задачи (см. ////triggers/on_save).
