_onDelta(d) {
    if (!d?.item || !d.token)
        return;
    const cur = this.streams[d.item] || {};
    const field = d.field === 'reasoning' ? 'reasoning' : 'content';
    this.streams = { ...this.streams, [d.item]: { ...cur, [field]: (cur[field] || '') + d.token } };
    this._lastDelta = Date.now();
    if (this.status !== 'running')
        this.status = 'running';
    this._stick();
},

_reloadTask() {
    if (!this.taskItem)
        return;
    if (this._loading) {
        this._again = true;
        return;
    }
    this._loading = (async () => {
        let tries = 0;
        try {
            do {
                this._again = false;
                try {
                    const raw = await this.taskItem?.load();
                    const data = typeof raw === 'string' ? JSON.parse(raw || '{}') : (raw || {});
                    const done = new Set((data.items || []).filter(i => i.type === 'assistant' && i.durationMs).map(i => i.id));
                    if (Object.keys(this.streams).some(id => done.has(id))) {
                        const s = {};
                        for (const [id, v] of Object.entries(this.streams)) {
                            if (!done.has(id))
                                s[id] = v;
                        }
                        this.streams = s;
                    }
                    this.data = data;
                    this.status = data.status || 'idle';
                    if (this.items.length)
                        this.optimistic = null;
                    this._lastDelta = Date.now();
                    this._stick();
                    tries = 0;
                }
                catch {
                    if (++tries > 4)
                        break;
                    this._again = true;
                    await new Promise(r => setTimeout(r, 250 * tries));
                }
            } while (this._again);
        }
        finally {
            this._loading = null;
        }
    })();
},

optimisticUser(text, attachments = []) {
    if (!text && !attachments?.length)
        return;
    this.optimistic = { id: 'optimistic', type: 'user', content: text, attachments, time: Date.now() };
    this.pinned = true;
    this.status = 'running';
    this._stick();
},

