async function testChat(extra = {}, headersExtra = {}, sysSuffix = '') {
    const t0 = Date.now();
    const res = await fetch('https://models.odant.org/v1/chat/completions', {
        method: 'POST',
        headers: {
            'Authorization': 'Bearer sk-bf-b988107b-9e43-4e36-813c-940fb07313d1',
            'Content-Type': 'application/json',
            ...headersExtra,
        },
        body: JSON.stringify({
            model: 'Qwen/Qwen3.8-27B-FP8',
            messages: [
                { role: 'system', content: 'Отвечай кратко по-русски.' + sysSuffix },
                { role: 'user', content: 'Привет! Как дела?' },
            ],
            max_tokens: 200,
            ...extra,
        }),
    });
    const data = await res.json();
    const msg = data.choices?.[0]?.message || {};
    return {
        ms: Date.now() - t0,
        reasoning_len: (msg.reasoning_content || msg.reasoning || '').length,
        content: msg.content,
        completion_tokens: data.usage?.completion_tokens,
    };
}

const [baseline, withKwargs, withNoThink] = await Promise.all([
    testChat({ reasoning_effort: 'none' }),
    testChat({ chat_template_kwargs: { enable_thinking: false } }, { 'x-bf-passthrough-extra-params': 'true' }),
    testChat({}, {}, '\n/no_think'),
]);
return { baseline, withKwargs, withNoThink };

