    const t0 = Date.now();
    const res = await fetch('https://models.odant.org/v1/chat/completions', {
        method: 'POST',
        headers: {
            'Authorization': 'Bearer sk-bf-b988107b-9e43-4e36-813c-940fb07313d1',
            'Content-Type': 'application/json',
            'x-bf-passthrough-extra-params': 'true',
        },
        body: JSON.stringify({
            model: 'Qwen/Qwen3.8-27B-FP8',
            messages: [
                { role: 'system', content: 'Ты ИИ-ассистент WORK. На простые реплики отвечай сразу, для задач используй инструменты.' },
                { role: 'user', content: userText },
            ],
            tools: dummyTools,
            max_tokens: 300,
            ...effortObj,
        }),
    });
    const data = await res.json();
