onScroll(e) {
    const el = e.target;
    const pinned = el.scrollHeight - el.scrollTop - el.clientHeight < 60;
    if (pinned !== this.pinned)
        this.pinned = pinned;
},

_stick() {
    if (!this.pinned)
        return;
    cancelAnimationFrame(this._raf);
    this._raf = requestAnimationFrame(() => {
        const el = this.$('.scroller');
