/**
 * Подсчитать активные пользовательские места (уникальные вошедшие uid в $server.sessions).
 */
export function getActiveWorkplaces(sessionsMap = globalThis.$server?.sessions) {
    const map = sessionsMap || {};
    const now = Date.now();
    const activeByUid = new Map();
    for (const s of Object.values(map)) {
        if (!s?.uid || s.ephemeral || s.principal?.kind === 'node')
            continue;
        const hasOpenSocket = s.sockets && Object.values(s.sockets).some(sock => sock?.ws?.readyState === 1);
        const recentHttp = (now - (s.lastSeen || s.created || 0)) < 30 * 60_000;
        if (!hasOpenSocket && !recentHttp)
            continue;
        const prev = activeByUid.get(s.uid);
        if (!prev || (s.lastSeen || 0) > (prev.lastSeen || 0)) {
            activeByUid.set(s.uid, {
                uid: s.uid,
                name: s.credentials?.label || s.credentials?.name || s.$user?.DATA?.label || s.uid,
                email: s.credentials?.email || s.$user?.DATA?.email || '',
                lastSeen: s.lastSeen || s.created || now,
                online: !!hasOpenSocket,
            });
        }
    }
    return [...activeByUid.values()];
}

/**
 * Проверить доступность рабочего места перед входом пользователя.
 * Если пользователь уже занимает место или является глобальным ADMIN сервера — вход разрешён.
 * Если все места (5 вечных + активные годовые) заняты другими пользователями — выбрасывает ошибку.
 */
export function assertWorkplaceAvailableForLogin(uid, { sessions, license, isAdmin = false } = {}) {
    if (!uid)
        return true;
    const licState = evaluateLicenseState(license || loadLocalLicense());
    const activeUsers = getActiveWorkplaces(sessions);
    if (activeUsers.some(u => u.uid === uid))
        return true;
    if (isAdmin)
        return true;
    if (activeUsers.length >= licState.totalSeats) {
        throw new Error(
            `Достигнут лимит рабочих мест по лицензии ПАК WORK (${activeUsers.length} из ${licState.totalSeats}: `
            + `${licState.baseSeats} вечных + ${licState.addonSeats} годовых). `
            + `Для подключения дополнительных сотрудников оформите годовую лицензию (Start / Business / Enterprise) на ${licState.hubUrl}`
        );
    }
    return true;
}

