export default {
    icon: 'carbon:certificate',
    label: 'Лицензия ПАК',
    roles: ['ADMIN', 'BOSS'],
    order: 3,
    allowUse($context) {
        return $context?.type === '$server';
    },
};

export default {
    imports: 'oda//button, oda//icon',
    template: /* html */`
        <style>
            :host {
                @apply --vertical;
                @apply --flex;
                overflow: auto;
                padding: 20px;
                gap: 20px;
                box-sizing: border-box;
                background: var(--body-background, #f6f8fb);
                color: var(--content-color, #1e293b);
            }
            .grid-top {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 16px;
            }
            .card {
                background: var(--content-background, #fff);
                border: 1px solid var(--subtle-border, #e2e8f0);
                border-radius: 12px;
                padding: 18px 20px;
                display: flex;
                flex-direction: column;
                gap: 12px;
                box-shadow: 0 1px 3px rgba(0,0,0,.04);
            }
            .card-head {
                display: flex;
                align-items: center;
                justify-content: space-between;
                gap: 10px;
            }
            .card-title {
                font-size: 16px;
                font-weight: 700;
                display: flex;
                align-items: center;
                gap: 8px;
            }
            .badge {
                padding: 4px 10px;
                border-radius: 999px;
                font-size: 12px;
                font-weight: 600;
                background: rgba(16, 185, 129, 0.14);
                color: #059669;
            }
            .badge.warn {
                background: rgba(245, 158, 11, 0.15);
                color: #d97706;
            }
            .kv-list {
                display: flex;
                flex-direction: column;
                gap: 6px;
                font-size: 13px;
            }
            .kv-row {
                display: flex;
                justify-content: space-between;
                gap: 12px;
                padding: 4px 0;
                border-bottom: 1px dashed var(--subtle-border, #e2e8f0);
            }
            .kv-label {
                color: var(--muted-color, #64748b);
            }
            .kv-val {
                font-weight: 600;
                text-align: right;
                font-family: monospace;
            }
            .seats-meter {
                display: flex;
                align-items: baseline;
                gap: 10px;
            }
            .seats-big {
                font-size: 28px;
                font-weight: 800;
                color: var(--accent-color, #2563eb);
            }
            .models-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
                gap: 10px;
            }
            .model-box {
                border: 1px solid var(--subtle-border, #e2e8f0);
                border-radius: 8px;
                padding: 10px 12px;
                display: flex;
                flex-direction: column;
                gap: 4px;
            }
            .model-title {
                font-weight: 700;
                font-size: 14px;
            }
            .model-role {
                font-size: 12px;
                color: var(--muted-color, #64748b);
            }
            .tiers-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
                gap: 12px;
            }
            .tier-card {
                border: 2px solid var(--subtle-border, #e2e8f0);
                border-radius: 10px;
                padding: 14px;
                cursor: pointer;
                display: flex;
                flex-direction: column;
                gap: 8px;
                transition: border-color .15s, background .15s;
            }
            .tier-card[selected] {
                border-color: var(--accent-color, #2563eb);
                background: rgba(37, 99, 235, 0.04);
            }
            .tier-price {
                font-size: 20px;
                font-weight: 800;
                color: var(--accent-color, #2563eb);
            }
            .controls-row {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 12px;
                margin-top: 8px;
            }
            input, select, textarea {
                padding: 8px 10px;
                border-radius: 6px;
                border: 1px solid var(--subtle-border, #cbd5e1);
                background: var(--content-background, #fff);
                color: inherit;
                font-size: 13px;
            }
            .btn-primary {
                background: var(--accent-color, #2563eb);
                color: #fff;
                border: none;
                border-radius: 8px;
                padding: 9px 16px;
                font-weight: 600;
                cursor: pointer;
            }
            .btn-secondary {
                background: transparent;
                border: 1px solid var(--subtle-border, #cbd5e1);
                border-radius: 8px;
                padding: 8px 14px;
                font-weight: 600;
                cursor: pointer;
                color: inherit;
            }
            .notice {
                padding: 10px 14px;
                border-radius: 8px;
                background: rgba(37, 99, 235, 0.08);
                font-size: 13px;
            }
        </style>

        <div class="grid-top">
            <div class="card">
                <div class="card-head">
                    <div class="card-title">
                        <oda-icon icon="carbon:chip" :icon-size="20"></oda-icon>
                        <span>Паспорт ПАК WORK</span>
                    </div>
                    <span class="badge">{{status?.hardwareMatch !== false ? 'Железо привязано' : 'Проверка HWID'}}</span>
                </div>
                <div class="kv-list">
                    <div class="kv-row">
                        <span class="kv-label">Платформа ПАК</span>
                        <span class="kv-val">{{status?.pakSpec?.cpu || 'AMD Ryzen 495 8085'}} · {{status?.pakSpec?.ramGb || 192}} ГБ RAM · SSD {{status?.pakSpec?.ssdTb || 4}} ТБ</span>
                    </div>
                    <div class="kv-row">
                        <span class="kv-label">Hardware ID (HWID)</span>
                        <span class="kv-val">{{status?.hardware?.hwid || '—'}}</span>
                    </div>
                    <div class="kv-row">
                        <span class="kv-label">Ключ узла (#system/node-key.json)</span>
                        <span class="kv-val">{{status?.hardware?.nodeFingerprint || '—'}}</span>
                    </div>
                    <div class="kv-row">
                        <span class="kv-label">Номер лицензии</span>
                        <span class="kv-val">{{status?.licenseId || '—'}}</span>
                    </div>
                </div>
            </div>

            <div class="card">
                <div class="card-head">
                    <div class="card-title">
                        <oda-icon icon="carbon:user-multiple" :icon-size="20"></oda-icon>
                        <span>Одновременные сессии (рабочие места)</span>
                    </div>
                    <span class="badge">Вечная база: {{status?.baseSeats || 5}} мест</span>
                </div>
                <div class="seats-meter">
                    <span class="seats-big">{{status?.activeSeatsCount || 0}} / {{status?.totalSeats || 5}}</span>
                    <span>активных сессий ({{status?.baseSeats || 5}} вечных + {{status?.addonSeats || 0}} срочных годовых)</span>
                </div>
                <div class="kv-list">
                    <div class="kv-row">
                        <span class="kv-label">Уровень поддержки (SLA)</span>
                        <span class="kv-val">{{status?.support?.tierName || 'Business'}} ({{status?.support?.reactionText || 'до 2 часов'}})</span>
                    </div>
                    <div class="kv-row">
                        <span class="kv-label">Включённый 1-й год поддержки ПАК</span>
                        <span class="kv-val">{{baseSupportText}}</span>
                    </div>
                    <div class="kv-row">
                        <span class="kv-label">Лимит обращений в год</span>
                        <span class="kv-val">{{status?.support?.ticketsRemaining ?? 0}} из {{status?.support?.ticketsQuota ?? 0}}</span>
                    </div>
                    <div class="kv-row">
