        <div class="card">
            <div class="card-head">
                <div class="card-title">
                    <oda-icon icon="carbon:machine-learning-model" :icon-size="20"></oda-icon>
                    <span>Предустановленный локальный стек ИИ ПАК WORK</span>
                </div>
