/**
 * Рассчитать стоимость заказа (покупка базового ПАК и/или докупка годовых пользовательских мест).
 */
export function calculateOrderQuote({
    includeBasePak = false,
    tier = 'business',
    addonSeats = 0,
    years = 1,
} = {}) {
    const tierKey = String(tier || 'business').toLowerCase();
    const tierSpec = SLA_TIERS[tierKey] || SLA_TIERS.business;
    const seats = Math.max(0, Math.floor(Number(addonSeats || 0)));
    const periodYears = Math.max(1, Math.min(5, Math.floor(Number(years || 1))));

    const baseAmountRub = includeBasePak ? PAK_PRODUCT.basePriceRub : 0;
    const addonsAmountRub = seats * tierSpec.pricePerUserYearRub * periodYears;
    const totalAmountRub = baseAmountRub + addonsAmountRub;

    const items = [];
    if (includeBasePak) {
        items.push({
            title: `${PAK_PRODUCT.name} (${PAK_PRODUCT.hardware.cpu}, ${PAK_PRODUCT.hardware.ramGb} ГБ RAM, SSD ${PAK_PRODUCT.hardware.ssdTb} ТБ, вечная лицензия на 5 мест + 1 год поддержки)`,
            quantity: 1,
            unitPriceRub: PAK_PRODUCT.basePriceRub,
            totalRub: PAK_PRODUCT.basePriceRub,
        });
    }
    if (seats > 0) {
        items.push({
            title: `Годовая лицензия WORK на доп. рабочее место (уровень поддержки ${tierSpec.name}, ${periodYears} г.)`,
            quantity: seats,
            unitPriceRub: tierSpec.pricePerUserYearRub * periodYears,
            totalRub: addonsAmountRub,
        });
    }

    return {
        includeBasePak: !!includeBasePak,
        basePakPriceRub: baseAmountRub,
        baseSeats: includeBasePak ? PAK_PRODUCT.baseSeats : 0,
        includedSupportYears: includeBasePak ? PAK_PRODUCT.includedSupportYears : 0,
        tier: tierSpec.id,
        tierName: tierSpec.name,
        pricePerUserYearRub: tierSpec.pricePerUserYearRub,
        addonSeats: seats,
        years: periodYears,
        addonsAmountRub,
        totalAmountRub,
        reactionMinutes: tierSpec.reactionMinutes,
        reactionLabel: tierSpec.reactionLabel,
        ticketsAdded: seats * tierSpec.ticketsLimitPerSeatYear * periodYears,
        items,
    };
}

/**
 * Криптографическое ядро центра лицензирования work.odant.org (Ed25519).
 * Подписывает и проверяет сертификаты лицензий ПАК WORK (WORK-LIC-v1),
 * привязанные к Hardware ID (AMD Ryzen CPU/MB) и ключу узла (#system/node-key.json).
 */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { PAK_PRODUCT } from './catalog.js';

export const LICENSE_PROTOCOL = 'WORK-LIC-v1';

/**
 * Загрузить или сгенерировать ключевую пару Ed25519 центра лицензирования.
 */
export function loadOrCreateAuthorityKeys(keyFilePath) {
    if (keyFilePath && fs.existsSync(keyFilePath)) {
        try {
            const raw = JSON.parse(fs.readFileSync(keyFilePath, 'utf8'));
            if (raw?.publicKey && raw?.privateKey)
                return raw;
        }
        catch { /* создадим заново */ }
    }
    const pair = crypto.generateKeyPairSync('ed25519');
    const keys = {
        publicKey: pair.publicKey.export({ type: 'spki', format: 'der' }).toString('base64'),
        privateKey: pair.privateKey.export({ type: 'pkcs8', format: 'der' }).toString('base64'),
        created: Date.now(),
    };
    if (keyFilePath) {
        fs.mkdirSync(path.dirname(keyFilePath), { recursive: true });
        fs.writeFileSync(keyFilePath, JSON.stringify(keys, null, 2), { mode: 0o600 });
    }
    return keys;
}

/**
 * Каноническая строка сертификата лицензии (полностью совместима с клиентским модулем WORK).
 */
export function canonicalLicenseString(lic = {}) {
    const clean = {
        protocol: lic.protocol || LICENSE_PROTOCOL,
        licenseId: String(lic.licenseId || ''),
        issuedAt: Number(lic.issuedAt || 0),
        issuer: String(lic.issuer || 'work.odant.org'),
        customer: {
            name: String(lic.customer?.name || ''),
            inn: String(lic.customer?.inn || ''),
            email: String(lic.customer?.email || ''),
        },
        hardware: {
            hwid: String(lic.hardware?.hwid || ''),
            nodeFingerprint: String(lic.hardware?.nodeFingerprint || ''),
            sku: String(lic.hardware?.sku || PAK_PRODUCT.sku),
        },
        baseSeats: Number(lic.baseSeats ?? PAK_PRODUCT.baseSeats),
        perpetualBase: lic.perpetualBase !== false,
        addonSubscriptions: Array.isArray(lic.addonSubscriptions)
            ? lic.addonSubscriptions.map(sub => ({
                id: String(sub.id || ''),
                tier: String(sub.tier || 'start').toLowerCase(),
                seats: Number(sub.seats || 0),
                issuedAt: Number(sub.issuedAt || 0),
                expiresAt: Number(sub.expiresAt || 0),
                orderId: String(sub.orderId || ''),
                status: String(sub.status || 'active'),
            }))
            : [],
    };
    return JSON.stringify(clean);
}

/**
 * Подписать сертификат лицензии закрытым ключом центра сертификации.
 */
export function signCertificate(lic, authorityKeys) {
    const priv = crypto.createPrivateKey({
        key: Buffer.from(String(authorityKeys.privateKey), 'base64'),
        format: 'der',
        type: 'pkcs8',
    });
    const payload = canonicalLicenseString(lic);
    const signature = crypto.sign(null, Buffer.from(payload, 'utf8'), priv).toString('base64');
    return {
        ...lic,
        protocol: lic.protocol || LICENSE_PROTOCOL,
        issuer: lic.issuer || 'work.odant.org',
        issuerPublicKey: authorityKeys.publicKey,
        signature,
    };
}

/**
 * Проверить подпись сертификата лицензии.
 */
export function verifyCertificate(lic, publicKeyB64 = '') {
    if (!lic || typeof lic !== 'object' || !lic.signature)
        return false;
    const pubKey = publicKeyB64 || lic.issuerPublicKey;
    if (!pubKey)
        return false;
    try {
        const pub = crypto.createPublicKey({
            key: Buffer.from(String(pubKey), 'base64'),
            format: 'der',
            type: 'spki',
        });
        const payload = canonicalLicenseString(lic);
        return crypto.verify(
            null,
            Buffer.from(payload, 'utf8'),
            pub,
            Buffer.from(String(lic.signature), 'base64')
        );
    }
    catch {
        return false;
    }
}

/**
 * Хранилище лицензионного сервера work.odant.org:
 *  - Реестр выпущенных лицензий ПАК (вечные 5 мест + 1 год включённой поддержки + срочные годовые расширения);
 *  - Заказы и платежи ЮKassa;
 *  - Привязки клиентских чатов (MAX, Telegram, VK) по коду привязки или номеру лицензии;
 *  - Тикеты техподдержки с расчётом SLA времени реакции и лимитов обращений по уровням Start / Business / Enterprise.
 */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { PAK_PRODUCT, SLA_TIERS, calculateOrderQuote } from './catalog.js';
import { loadOrCreateAuthorityKeys, signCertificate } from './crypto.js';

const ONE_YEAR_MS = 365 * 24 * 3600_000;

export class LicenseStore {
    constructor({ dataDir = './data' } = {}) {
        this.dataDir = dataDir;
        fs.mkdirSync(this.dataDir, { recursive: true });
        this.stateFile = path.join(this.dataDir, 'store.json');
        this.keyFile = path.join(this.dataDir, 'authority-key.json');
        this.authorityKeys = loadOrCreateAuthorityKeys(this.keyFile);

        this.state = {
            licenses: {},
            orders: {},
            tickets: {},
            botBindings: {},
        };
        this._load();
    }

    _load() {
        if (!fs.existsSync(this.stateFile))
            return;
        try {
            const raw = JSON.parse(fs.readFileSync(this.stateFile, 'utf8'));
            if (raw && typeof raw === 'object') {
                this.state.licenses = raw.licenses || {};
                this.state.orders = raw.orders || {};
                this.state.tickets = raw.tickets || {};
                this.state.botBindings = raw.botBindings || {};
            }
        }
        catch { /* начинаем с чистого состояния */ }
    }

    _save() {
        const tmp = `${this.stateFile}.${process.pid}.tmp`;
        fs.writeFileSync(tmp, JSON.stringify(this.state, null, 2), 'utf8');
        fs.renameSync(tmp, this.stateFile);
    }

    /**
     * Зарегистрировать или обновить базовую лицензию ПАК (5 вечных мест + 1 год включённой поддержки).
     */
    issueOrUpdateLicense({
        licenseId,
        hwid = '',
        nodeFingerprint = '',
        customer = {},
        baseSeats = PAK_PRODUCT.baseSeats,
        includedSupportTier = PAK_PRODUCT.includedSupportTier,
    } = {}) {
        const now = Date.now();
        let existing = licenseId ? this.state.licenses[licenseId] : null;
        if (!existing && hwid) {
            existing = Object.values(this.state.licenses).find(l => l.hardware?.hwid === hwid) || null;
        }

        const id = existing?.licenseId || licenseId || ('WORK-PAK-' + crypto.randomBytes(4).toString('hex').toUpperCase());
        const issuedAt = existing?.issuedAt || now;
        const bindCode = existing?.support?.bindCode || ('BIND-' + crypto.randomBytes(3).toString('hex').toUpperCase());

        const record = {
            licenseId: id,
            issuedAt,
            updatedAt: now,
            issuer: 'work.odant.org',
            customer: {
                name: customer.name || existing?.customer?.name || 'Организация ПАК WORK',
                inn: customer.inn || existing?.customer?.inn || '',
                email: customer.email || existing?.customer?.email || '',
                phone: customer.phone || existing?.customer?.phone || '',
            },
            hardware: {
                hwid: hwid || existing?.hardware?.hwid || ('PAK-' + crypto.randomBytes(6).toString('hex').toUpperCase()),
                nodeFingerprint: nodeFingerprint || existing?.hardware?.nodeFingerprint || '',
                sku: PAK_PRODUCT.sku,
                cpu: PAK_PRODUCT.hardware.cpu,
                ramGb: PAK_PRODUCT.hardware.ramGb,
                ssdTb: PAK_PRODUCT.hardware.ssdTb,
            },
            baseSeats: Number(baseSeats ?? existing?.baseSeats ?? PAK_PRODUCT.baseSeats),
            perpetualBase: true,
            addonSubscriptions: Array.isArray(existing?.addonSubscriptions) ? existing.addonSubscriptions : [],
            support: {
                tier: existing?.support?.tier || includedSupportTier || 'business',
                includedUntil: existing?.support?.includedUntil || (issuedAt + ONE_YEAR_MS),
                ticketsUsed: Number(existing?.support?.ticketsUsed || 0),
                bindCode,
            },
        };

        const signed = signCertificate(record, this.authorityKeys);
        this.state.licenses[id] = signed;
        this._save();
        return this.getLicenseSummary(id);
    }

    /**
     * Добавить срочную годовую подписку на дополнительные пользовательские места (после оплаты ЮKassa).
     */
    grantAddonSubscription(licenseId, { tier = 'business', seats = 1, years = 1, orderId = '', paymentId = '' } = {}) {
        let lic = this.state.licenses[licenseId];
        if (!lic) {
            this.issueOrUpdateLicense({ licenseId });
            lic = this.state.licenses[licenseId];
        }
        const now = Date.now();
        const tierKey = String(tier || 'business').toLowerCase();
        const tierSpec = SLA_TIERS[tierKey] || SLA_TIERS.business;
        const seatsCount = Math.max(0, Number(seats || 0));
        const yearsCount = Math.max(1, Number(years || 1));

        if (seatsCount > 0) {
            // Ищем, не была ли уже выдана подписка по этому orderId (идемпотентность webhook ЮKassa)
            const already = (lic.addonSubscriptions || []).find(s => orderId && s.orderId === orderId);
            if (!already) {
                lic.addonSubscriptions.push({
                    id: 'SUB-' + crypto.randomBytes(4).toString('hex').toUpperCase(),
                    tier: tierSpec.id,
                    seats: seatsCount,
                    years: yearsCount,
                    issuedAt: now,
                    expiresAt: now + yearsCount * ONE_YEAR_MS,
                    orderId: String(orderId || ''),
                    paymentId: String(paymentId || ''),
                    status: 'active',
                });
            }
        }

        // Повышаем активный уровень поддержки, если докуплен более высокий тариф
        const rank = { start: 1, business: 2, enterprise: 3 };
        if ((rank[tierSpec.id] || 0) > (rank[lic.support?.tier] || 0)) {
            lic.support.tier = tierSpec.id;
        }
        lic.updatedAt = now;
        const signed = signCertificate(lic, this.authorityKeys);
        this.state.licenses[licenseId] = signed;
        this._save();
        return this.getLicenseSummary(licenseId);
    }

    /**
     * Получить развёрнутую сводку по лицензии (с расчётом активных мест, SLA и квоты обращений).
     */
    getLicenseSummary(licenseIdOrCode, now = Date.now()) {
        const lic = this.findLicense(licenseIdOrCode);
        if (!lic)
            return null;

        const baseSeats = Number(lic.baseSeats ?? PAK_PRODUCT.baseSeats);
        const baseSupportUntil = Number(lic.support?.includedUntil || (lic.issuedAt + ONE_YEAR_MS));
        const baseSupportActive = baseSupportUntil > now;

        let addonSeats = 0;
        let highestTier = baseSupportActive ? (lic.support?.tier || 'business') : null;
        let ticketsQuota = baseSupportActive
            ? baseSeats * (SLA_TIERS[lic.support?.tier || 'business']?.ticketsLimitPerSeatYear || 48)
            : 0;

        const rank = { start: 1, business: 2, enterprise: 3 };
        const activeAddons = [];

        for (const sub of (lic.addonSubscriptions || [])) {
            if (sub.status === 'active' && Number(sub.expiresAt) > now && Number(sub.seats) > 0) {
                const tSpec = SLA_TIERS[sub.tier] || SLA_TIERS.start;
                addonSeats += Number(sub.seats);
                ticketsQuota += Number(sub.seats) * tSpec.ticketsLimitPerSeatYear;
                if (!highestTier || (rank[tSpec.id] || 0) > (rank[highestTier] || 0))
                    highestTier = tSpec.id;
                activeAddons.push({ ...sub, tierName: tSpec.name });
            }
        }

        const effectiveTier = SLA_TIERS[highestTier || lic.support?.tier || 'start'] || SLA_TIERS.start;
        if (ticketsQuota === 0)
            ticketsQuota = baseSeats * SLA_TIERS.start.ticketsLimitPerSeatYear;

        const ticketsUsed = Number(lic.support?.ticketsUsed || 0);

        return {
            licenseId: lic.licenseId,
            issuedAt: lic.issuedAt,
            updatedAt: lic.updatedAt,
            customer: lic.customer,
            hardware: lic.hardware,
            baseSeats,
            perpetualBase: true,
            addonSeats,
            totalSeats: baseSeats + addonSeats,
            baseSupportUntil,
            baseSupportActive,
            activeAddons,
            support: {
                active: baseSupportActive || activeAddons.length > 0,
                tier: effectiveTier.id,
                tierName: effectiveTier.name,
                reactionMinutes: effectiveTier.reactionMinutes,
                reactionLabel: effectiveTier.reactionLabel,
                scheduleLabel: effectiveTier.scheduleLabel,
                ticketsQuota,
                ticketsUsed,
                ticketsRemaining: Math.max(0, ticketsQuota - ticketsUsed),
                bindCode: lic.support?.bindCode || '',
            },
            certificate: lic,
        };
    }

    /**
     * Найти лицензию по licenseId, HWID или коду привязки бота (bindCode).
     */
    findLicense(query) {
        const q = String(query || '').trim();
        if (!q)
            return null;
        if (this.state.licenses[q])
            return this.state.licenses[q];
        const upper = q.toUpperCase();
        for (const lic of Object.values(this.state.licenses)) {
            if (
                lic.licenseId.toUpperCase() === upper
                || lic.hardware?.hwid?.toUpperCase() === upper
                || lic.support?.bindCode?.toUpperCase() === upper
            ) {
                return lic;
            }
        }
        return null;
    }

    listLicenses() {
        return Object.keys(this.state.licenses).map(id => this.getLicenseSummary(id));
    }

    /**
     * Создать заказ на покупку ПАК и/или дополнительных годовых лицензий.
     */
    createOrder({
        licenseId = '',
        hwid = '',
        nodeFingerprint = '',
        includeBasePak = false,
        tier = 'business',
        addonSeats = 0,
        years = 1,
        customer = {},
        returnUrl = '',
    } = {}) {
        const quote = calculateOrderQuote({ includeBasePak, tier, addonSeats, years });
        if (quote.totalAmountRub <= 0)
            throw new Error('Сумма заказа должна быть больше 0 ₽');

        let targetLic = this.findLicense(licenseId || hwid);
        if (!targetLic) {
            targetLic = this.issueOrUpdateLicense({
                licenseId: licenseId || undefined,
                hwid,
                nodeFingerprint,
                customer,
            });
        }

        const orderId = 'ORD-' + Date.now().toString(36).toUpperCase() + '-' + crypto.randomBytes(2).toString('hex').toUpperCase();
        const order = {
            orderId,
            licenseId: targetLic.licenseId,
            includeBasePak: quote.includeBasePak,
            tier: quote.tier,
            tierName: quote.tierName,
            addonSeats: quote.addonSeats,
            years: quote.years,
            amountRub: quote.totalAmountRub,
            items: quote.items,
            customer: {
                name: customer.name || targetLic.customer?.name || 'Организация WORK',
                inn: customer.inn || targetLic.customer?.inn || '',
                email: customer.email || targetLic.customer?.email || 'billing@odant.org',
                phone: customer.phone || targetLic.customer?.phone || '',
            },
            status: 'pending',
            paymentId: '',
            confirmationUrl: '',
            returnUrl: returnUrl || 'https://work.odant.org',
            createdAt: Date.now(),
            paidAt: null,
        };

        this.state.orders[orderId] = order;
        this._save();
        return order;
    }

    getOrder(orderId) {
        return this.state.orders[orderId] || null;
    }

    findOrderByPaymentId(paymentId) {
        if (!paymentId)
            return null;
        return Object.values(this.state.orders).find(o => o.paymentId === paymentId) || null;
    }

    updateOrder(orderId, patch = {}) {
        const ord = this.state.orders[orderId];
        if (!ord)
            return null;
        Object.assign(ord, patch);
        this._save();
        return ord;
    }

    /**
     * Отметить заказ как оплаченный и выпустить/продлить лицензию.
     */
    completePaidOrder(orderId, { paymentId = '' } = {}) {
        const ord = this.state.orders[orderId];
        if (!ord)
            throw new Error(`Заказ ${orderId} не найден`);
        if (ord.status === 'paid') {
            return {
                order: ord,
                license: this.getLicenseSummary(ord.licenseId),
                alreadyProcessed: true,
            };
        }
        ord.status = 'paid';
        ord.paidAt = Date.now();
        if (paymentId)
            ord.paymentId = paymentId;

        const license = this.grantAddonSubscription(ord.licenseId, {
            tier: ord.tier,
            seats: ord.addonSeats,
            years: ord.years,
            orderId: ord.orderId,
            paymentId: ord.paymentId,
        });
        this._save();
        return { order: ord, license, alreadyProcessed: false };
    }

    /**
     * Привязать чат мессенджера (MAX, Telegram, VK) к лицензии ПАК.
     */
    bindBotChat({ channel, chatId, userName = '', codeOrLicenseId }) {
        const lic = this.findLicense(codeOrLicenseId);
        if (!lic)
            throw new Error('Лицензия или код привязки не найден. Проверьте код в разделе «Лицензия ПАК» вашего сервера WORK.');
        const key = `${String(channel).toLowerCase()}:${String(chatId)}`;
        this.state.botBindings[key] = {
            channel: String(channel).toLowerCase(),
            chatId: String(chatId),
            userName: String(userName || ''),
            licenseId: lic.licenseId,
            boundAt: Date.now(),
        };
        this._save();
        return this.getLicenseSummary(lic.licenseId);
    }

    getBoundLicenseForChat(channel, chatId) {
        const key = `${String(channel).toLowerCase()}:${String(chatId)}`;
        const binding = this.state.botBindings[key];
        if (!binding?.licenseId)
            return null;
        return this.getLicenseSummary(binding.licenseId);
    }

    getBindingsForLicense(licenseId) {
        return Object.values(this.state.botBindings).filter(b => b.licenseId === licenseId);
    }

    /**
     * Создать обращение (тикет) в техподдержку из MAX, Telegram, VK или веб-панели
     * с автоматическим контролем квоты обращений и SLA времени реакции по тарифу (Start / Business / Enterprise).
     */
    createSupportTicket({
        licenseId,
        channel = 'telegram',
        chatId = '',
        userName = 'Клиент',
        text = '',
    }) {
        const summary = this.getLicenseSummary(licenseId);
        if (!summary)
            throw new Error('Лицензия ПАК не найдена');

        if (summary.support.ticketsRemaining <= 0) {
            throw new Error(
                `Исчерпан годовой лимит обращений по тарифу ${summary.support.tierName} `
                + `(${summary.support.ticketsUsed}/${summary.support.ticketsQuota}). `
                + `Для увеличения лимита и ускорения реакции перейдите на тариф Business или Enterprise на https://work.odant.org`
            );
        }

        const rawLic = this.state.licenses[summary.licenseId];
        rawLic.support.ticketsUsed = Number(rawLic.support?.ticketsUsed || 0) + 1;

        const now = Date.now();
        const reactionMinutes = summary.support.reactionMinutes;
        const slaDeadlineAt = now + reactionMinutes * 60_000;
        const ticketId = 'TCK-' + Object.keys(this.state.tickets).length.toString().padStart(4, '0') + '-' + crypto.randomBytes(2).toString('hex').toUpperCase();

        const ticket = {
            ticketId,
            licenseId: summary.licenseId,
            customerName: summary.customer?.name || 'Клиент ПАК WORK',
            channel: String(channel).toLowerCase(),
            chatId: String(chatId),
            userName: String(userName),
            tier: summary.support.tier,
            tierName: summary.support.tierName,
            reactionMinutes,
            reactionLabel: summary.support.reactionLabel,
            slaDeadlineAt,
            status: 'open',
            createdAt: now,
            firstReplyAt: null,
            slaMet: null,
            messages: [
                {
                    from: 'client',
                    author: userName,
                    text: String(text || '').trim(),
                    time: now,
                },
            ],
        };

        this.state.tickets[ticketId] = ticket;
        this._save();
        return {
            ticket,
            license: this.getLicenseSummary(summary.licenseId),
        };
    }

    /**
     * Ответить на тикет от лица инженера поддержки (и зафиксировать выполнение SLA времени реакции).
     */
    replyToTicket(ticketId, { engineerName = 'Инженер поддержки ODANT', text = '' } = {}) {
        const t = this.state.tickets[ticketId];
        if (!t)
            throw new Error(`Тикет ${ticketId} не найден`);
        const now = Date.now();
        if (!t.firstReplyAt) {
            t.firstReplyAt = now;
            t.slaMet = now <= t.slaDeadlineAt;
        }
        t.status = 'answered';
        t.messages.push({
            from: 'support',
            author: engineerName,
            text: String(text || '').trim(),
            time: now,
        });
        this._save();
        return t;
    }

    listTickets({ licenseId = '' } = {}) {
        const all = Object.values(this.state.tickets).sort((a, b) => b.createdAt - a.createdAt);
        if (licenseId)
            return all.filter(t => t.licenseId === licenseId);
        return all;
    }
}

/**
 * Интеграция платёжного шлюза ЮKassa (API v3: https://api.yookassa.ru/v3/payments)
 * для продажи ПАК WORK и дополнительных годовых пользовательских лицензий (Start / Business / Enterprise).
 *
 * Поддерживает:
 *  - Боевой режим ЮKassa (Basic Auth shopId:secretKey, Idempotence-Key, 54-ФЗ чек receipt, metadata);
 *  - Встроенный песочный режим (когда боевые ключи не заданы в окружении) со страницей тестовой оплаты
 *    /pay/sandbox/:orderId, эмулирующей полный цикл ЮKassa вплоть до webhook payment.succeeded;
 *  - Обработку входящих webhook-уведомлений ЮKassa (payment.succeeded, payment.canceled, refund.succeeded).
 */
import crypto from 'node:crypto';

const YOOKASSA_API_URL = 'https://api.yookassa.ru/v3/payments';

export class YooKassaService {
    constructor({
        store,
        shopId = process.env.YOOKASSA_SHOP_ID || '',
        secretKey = process.env.YOOKASSA_SECRET_KEY || '',
        publicOrigin = process.env.PUBLIC_ORIGIN || 'https://work.odant.org',
        onOrderPaid = null,
        fetchImpl = globalThis.fetch,
    } = {}) {
        this.store = store;
        this.shopId = shopId;
        this.secretKey = secretKey;
        this.publicOrigin = String(publicOrigin).replace(/\/+$/, '');
        this.onOrderPaid = onOrderPaid;
        this.fetchImpl = fetchImpl;
    }

    get isLiveMode() {
        return Boolean(this.shopId && this.secretKey);
    }

    /**
     * Сформировать тело запроса к ЮKassa v3 (/v3/payments) с чеком по 54-ФЗ.
     */
    buildYooKassaPaymentPayload(order) {
        const valueStr = Number(order.amountRub || 0).toFixed(2);
        const description = order.includeBasePak
            ? `Заказ ${order.orderId}: ПАК WORK (5 вечных мест) + доп. лицензии (${order.addonSeats} мест, ${order.tierName})`
            : `Заказ ${order.orderId}: Годовая лицензия WORK (${order.addonSeats} польз., уровень ${order.tierName}, ${order.years} г.)`;

        return {
            amount: {
                value: valueStr,
                currency: 'RUB',
            },
            capture: true,
            confirmation: {
                type: 'redirect',
                return_url: order.returnUrl || `${this.publicOrigin}/?order=${encodeURIComponent(order.orderId)}`,
            },
            description: description.slice(0, 128),
            metadata: {
                orderId: order.orderId,
                licenseId: order.licenseId,
                tier: order.tier,
                addonSeats: String(order.addonSeats),
                years: String(order.years),
                includeBasePak: String(!!order.includeBasePak),
            },
            receipt: {
                customer: {
                    email: order.customer?.email || 'billing@odant.org',
                    ...(order.customer?.inn ? { inn: String(order.customer.inn) } : {}),
                    ...(order.customer?.name ? { full_name: String(order.customer.name) } : {}),
                },
                items: (order.items || []).map(item => ({
                    description: String(item.title || 'Лицензия WORK').slice(0, 128),
                    quantity: String(item.quantity || 1),
                    amount: {
                        value: Number(item.unitPriceRub || order.amountRub).toFixed(2),
                        currency: 'RUB',
                    },
                    vat_code: 1,
                    payment_mode: 'full_payment',
                    payment_subject: 'intellectual_activity',
                })),
            },
        };
    }

    /**
     * Создать платёж в ЮKassa (или в локальной песочнице, если не заданы боевые ключи).
     */
    async createPaymentForOrder(order, { originOverride = '' } = {}) {
        const baseOrigin = String(originOverride || this.publicOrigin).replace(/\/+$/, '');
        const body = this.buildYooKassaPaymentPayload(order);

        if (this.isLiveMode && typeof this.fetchImpl === 'function') {
            const idempotenceKey = crypto.randomUUID();
            const basicCreds = Buffer.from(`${this.shopId}:${this.secretKey}`, 'utf8').toString('base64');
            const res = await this.fetchImpl(YOOKASSA_API_URL, {
                method: 'POST',
                headers: {
                    'Authorization': `Basic ${basicCreds}`,
                    'Idempotence-Key': idempotenceKey,
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(body),
            });
            if (!res.ok) {
                const errText = await res.text().catch(() => '');
                throw new Error(`ЮKassa API вернула HTTP ${res.status}: ${errText.slice(0, 240)}`);
            }
            const payment = await res.json();
            const paymentId = payment.id;
            const confirmationUrl = payment.confirmation?.confirmation_url || '';
            this.store.updateOrder(order.orderId, {
                paymentId,
                confirmationUrl,
                yookassaMode: 'live',
            });
            return {
                orderId: order.orderId,
                licenseId: order.licenseId,
                amountRub: order.amountRub,
                paymentId,
                confirmationUrl,
                mode: 'live',
            };
        }

        // Песочница ЮKassa (для локального запуска и демонстрации без боевых ключей)
        const paymentId = 'yk_sandbox_' + crypto.randomBytes(8).toString('hex');
        const confirmationUrl = `${baseOrigin}/pay/sandbox/${encodeURIComponent(order.orderId)}`;
        this.store.updateOrder(order.orderId, {
            paymentId,
            confirmationUrl,
            yookassaMode: 'sandbox',
        });
        return {
            orderId: order.orderId,
            licenseId: order.licenseId,
            amountRub: order.amountRub,
            paymentId,
            confirmationUrl,
            mode: 'sandbox',
        };
    }

    /**
     * Обработать входящий HTTP Webhook от ЮKassa (/api/payments/yookassa/webhook).
     */
    async handleWebhook(notification = {}) {
        const event = String(notification.event || '');
        const obj = notification.object || {};
        const paymentId = String(obj.id || '');
        const orderId = String(obj.metadata?.orderId || '');

        let order = orderId ? this.store.getOrder(orderId) : null;
        if (!order && paymentId)
            order = this.store.findOrderByPaymentId(paymentId);

        if (!order) {
            return { ok: false, reason: 'order_not_found', event, orderId, paymentId };
        }

        if (event === 'payment.succeeded' || obj.status === 'succeeded') {
            const result = this.store.completePaidOrder(order.orderId, { paymentId });
            if (!result.alreadyProcessed && typeof this.onOrderPaid === 'function') {
                await Promise.resolve(this.onOrderPaid(result.order, result.license)).catch(() => {});
            }
            return {
                ok: true,
                status: 'paid',
                orderId: result.order.orderId,
                licenseId: result.license.licenseId,
                totalSeats: result.license.totalSeats,
                tier: result.license.support.tierName,
                alreadyProcessed: result.alreadyProcessed,
            };
        }

        if (event === 'payment.canceled' || obj.status === 'canceled') {
            this.store.updateOrder(order.orderId, { status: 'canceled' });
            return { ok: true, status: 'canceled', orderId: order.orderId };
        }

        return { ok: true, status: obj.status || 'ignored', orderId: order.orderId };
    }
}

/**
 * Омниканальный шлюз ботов технической поддержки ПАК WORK для мессенджеров:
 *  - MAX (https://botapi.max.ru)
 *  - Telegram (https://api.telegram.org)
 *  - VK (https://api.vk.com/method)
 *
 * Возможности:
 *  - Привязка чата к лицензии ПАК клиента (/bind <код_или_номер_лицензии>);
 *  - Сводка по ПАК, рабочим местам (5 вечных + годовые) и текущему уровню SLA (/status);
 *  - Докупка годовых пользовательских лицензий Start / Business / Enterprise через ЮKassa (/buy);
 *  - Приём обращений в техподдержку с проверкой квоты обращений и расчётом времени реакции по SLA:
 *      Start (15 000 ₽/год)      — до 12 обращений/год на место, реакция до 8 раб. часов;
 *      Business (40 000 ₽/год)   — до 48 обращений/год на место, реакция до 2 часов;
 *      Enterprise (100 000 ₽/год) — безлимит обращений, реакция до 15 минут (24/7);
 *  - Отправка ответов инженеров и уведомлений об успешной оплате обратно в MAX / Telegram / VK.
 */
import { SLA_TIERS } from './catalog.js';

export class SupportBotsHub {
    constructor({
        store,
        yookassa,
        maxBotSecret = process.env.MAX_BOT_TOKEN || '',
        telegramBotSecret = process.env.TELEGRAM_BOT_TOKEN || '',
        vkBotSecret = process.env.VK_BOT_TOKEN || '',
        vkConfirmationCode = process.env.VK_CONFIRMATION_CODE || 'work_vk_confirm',
        publicOrigin = process.env.PUBLIC_ORIGIN || 'https://work.odant.org',
        fetchImpl = globalThis.fetch,
    } = {}) {
        this.store = store;
        this.yookassa = yookassa;
        this.maxBotSecret = maxBotSecret;
        this.telegramBotSecret = telegramBotSecret;
        this.vkBotSecret = vkBotSecret;
        this.vkConfirmationCode = vkConfirmationCode;
        this.publicOrigin = String(publicOrigin).replace(/\/+$/, '');
        this.fetchImpl = fetchImpl;
        this.outboxLog = [];
    }

    /**
     * Универсальная обработка входящего сообщения от пользователя из любого мессенджера (max | telegram | vk).
     */
    async handleIncomingMessage({ channel, chatId, userName = 'Клиент', text = '', originOverride = '' }) {
        const ch = String(channel || 'telegram').toLowerCase();
        const cid = String(chatId || 'demo-chat');
        const cleanText = String(text || '').trim();

        if (!cleanText || /^\/(start|help|помощь)$/i.test(cleanText)) {
            const bound = this.store.getBoundLicenseForChat(ch, cid);
            const greeting = [
                `Здравствуйте, ${userName}! Это служба поддержки и лицензирования ПАК WORK (${ch.toUpperCase()}).`,
                bound
                    ? `Ваш чат привязан к лицензии: ${bound.licenseId} (${bound.customer?.name || 'ПАК WORK'}, уровень ${bound.support.tierName}, мест: ${bound.totalSeats}).`
                    : 'Для начала работы привяжите ваш ПАК WORK командой:\n/bind <НОМЕР_ЛИЦЕНЗИИ_ИЛИ_КОД>',
                '',
                'Доступные команды:',
                '• /bind <КОД> — привязать ПАК WORK к этому чату',
                '• /status — проверить рабочие места (5 вечных + годовые), SLA и остаток обращений',
                '• /buy <start|business|enterprise> <кол-во_мест> — докупить годовые лицензии через ЮKassa',
                '• Любое другое сообщение — создать обращение в инженерную поддержку по вашему SLA.',
            ].join('\n');
            await this.sendExternalMessage(ch, cid, greeting);
            return { action: 'help', reply: greeting };
        }

        // Команда /bind <код>
        const bindMatch = cleanText.match(/^\/(?:bind|привязать)\s+(\S+)/i);
        if (bindMatch) {
            const code = bindMatch[1].trim();
            try {
                const lic = this.store.bindBotChat({
                    channel: ch,
                    chatId: cid,
                    userName,
                    codeOrLicenseId: code,
                });
                const reply = [
                    `Чат (${ch.toUpperCase()}) успешно привязан к ПАК WORK!`,
                    `• Лицензия: ${lic.licenseId}`,
                    `• Организация: ${lic.customer?.name || '—'}`,
                    `• Платформа: ${lic.hardware?.cpu || 'AMD Ryzen 495 8085'} (${lic.hardware?.ramGb || 192} ГБ RAM, SSD ${lic.hardware?.ssdTb || 4} ТБ)`,
                    `• Рабочие места: ${lic.totalSeats} (${lic.baseSeats} вечных + ${lic.addonSeats} годовых)`,
                    `• Уровень поддержки: ${lic.support.tierName} (время реакции ${lic.support.reactionLabel})`,
                    `• Остаток обращений: ${lic.support.ticketsRemaining} из ${lic.support.ticketsQuota}`,
                ].join('\n');
                await this.sendExternalMessage(ch, cid, reply);
                return { action: 'bind', ok: true, licenseId: lic.licenseId, reply };
            }
            catch (err) {
                const reply = `Ошибка привязки: ${err.message || err}`;
                await this.sendExternalMessage(ch, cid, reply);
                return { action: 'bind', ok: false, reply };
            }
        }

        // Команда /status
        if (/^\/(status|статус)$/i.test(cleanText)) {
            const lic = this.store.getBoundLicenseForChat(ch, cid);
            if (!lic) {
                const reply = 'Чат ещё не привязан к лицензии ПАК. Отправьте /bind <НОМЕР_ЛИЦЕНЗИИ_ИЛИ_КОД>.';
                await this.sendExternalMessage(ch, cid, reply);
                return { action: 'status', ok: false, reply };
            }
            const reply = [
                `Статус лицензии ПАК WORK: ${lic.licenseId}`,
                `• Оборудование: ${lic.hardware?.cpu || 'AMD Ryzen 495 8085'} · ${lic.hardware?.ramGb || 192} ГБ RAM · SSD ${lic.hardware?.ssdTb || 4} ТБ`,
                `• HWID: ${lic.hardware?.hwid || '—'}`,
                `• Доступно одновременных сессий: ${lic.totalSeats} (${lic.baseSeats} вечных + ${lic.addonSeats} срочных годовых)`,
                `• Уровень SLA поддержки: ${lic.support.tierName} (${lic.support.scheduleLabel})`,
                `• Гарантированное время реакции: ${lic.support.reactionLabel}`,
                `• Доступно обращений в этом году: ${lic.support.ticketsRemaining} из ${lic.support.ticketsQuota}`,
            ].join('\n');
            await this.sendExternalMessage(ch, cid, reply);
            return { action: 'status', ok: true, license: lic, reply };
        }

        // Команда /buy <start|business|enterprise> [seats] [years]
        const buyMatch = cleanText.match(/^\/(?:buy|купить)\s*(?:(start|business|enterprise))?\s*(\d+)?\s*(\d+)?/i);
        if (buyMatch) {
            const lic = this.store.getBoundLicenseForChat(ch, cid);
            if (!lic) {
                const reply = 'Сначала привяжите ваш ПАК командой /bind <НОМЕР_ЛИЦЕНЗИИ>, чтобы докупить рабочие места.';
                await this.sendExternalMessage(ch, cid, reply);
                return { action: 'buy', ok: false, reply };
            }
            const tierKey = (buyMatch[1] || 'business').toLowerCase();
            const seats = Math.max(1, Number(buyMatch[2] || 1));
            const years = Math.max(1, Math.min(5, Number(buyMatch[3] || 1)));
            const tierSpec = SLA_TIERS[tierKey] || SLA_TIERS.business;

            const order = this.store.createOrder({
                licenseId: lic.licenseId,
                tier: tierSpec.id,
                addonSeats: seats,
                years,
                customer: lic.customer,
            });
            const payment = await this.yookassa.createPaymentForOrder(order, { originOverride });
            const reply = [
                `Сформирован счёт ЮKassa (${order.orderId}) для лицензии ${lic.licenseId}:`,
                `• Тариф поддержки: ${tierSpec.name} (${tierSpec.pricePerUserYearRub.toLocaleString('ru-RU')} ₽/год за 1 место)`,
                `• Доп. рабочих мест: ${seats} на ${years} г.`,
                `• Сумма к оплате: ${order.amountRub.toLocaleString('ru-RU')} ₽`,
                `• Ссылка на оплату ЮKassa: ${payment.confirmationUrl}`,
            ].join('\n');
            await this.sendExternalMessage(ch, cid, reply);
            return { action: 'buy', ok: true, orderId: order.orderId, confirmationUrl: payment.confirmationUrl, reply };
        }

        // Обычное сообщение -> создание тикета техподдержки с контролем SLA и лимита обращений
        const lic = this.store.getBoundLicenseForChat(ch, cid);
        if (!lic) {
            const reply = 'Для отправки обращения в техподдержку сначала привяжите ваш ПАК WORK командой:\n/bind <НОМЕР_ЛИЦЕНЗИИ_ИЛИ_КОД>';
            await this.sendExternalMessage(ch, cid, reply);
            return { action: 'unauthenticated', ok: false, reply };
        }

        try {
            const { ticket, license: updatedLic } = this.store.createSupportTicket({
                licenseId: lic.licenseId,
                channel: ch,
                chatId: cid,
                userName,
                text: cleanText,
            });
            const reply = [
                `Обращение ${ticket.ticketId} зарегистрировано!`,
                `• Тариф SLA: ${ticket.tierName} (гарантированное время реакции: ${ticket.reactionLabel})`,
                `• Остаток обращений по вашей квоте: ${updatedLic.support.ticketsRemaining} из ${updatedLic.support.ticketsQuota}`,
                'Инженер поддержки ответит вам прямо в этот чат.',
            ].join('\n');
            await this.sendExternalMessage(ch, cid, reply);
            return { action: 'ticket_created', ok: true, ticket, reply };
        }
        catch (err) {
            const reply = `Обращение не создано: ${err.message || err}`;
            await this.sendExternalMessage(ch, cid, reply);
            return { action: 'ticket_quota_exceeded', ok: false, reply };
        }
    }

    /**
     * Разбор нативного Webhook от мессенджера MAX (https://botapi.max.ru).
     */
    async handleMaxWebhook(payload = {}, originOverride = '') {
        const msg = payload.message || {};
        const sender = msg.sender || payload.user || {};
        const recipient = msg.recipient || {};
        const chatId = String(recipient.chat_id || sender.user_id || payload.chat_id || 'max-chat');
        const userName = String(sender.name || sender.username || 'Пользователь MAX');
        const text = String(msg.body?.text ?? payload.text ?? '');
        return this.handleIncomingMessage({ channel: 'max', chatId, userName, text, originOverride });
    }

    /**
     * Разбор нативного Webhook от Telegram Bot API.
     */
    async handleTelegramWebhook(payload = {}, originOverride = '') {
        const msg = payload.message || payload.edited_message || payload.callback_query?.message || {};
        const from = msg.from || payload.callback_query?.from || {};
        const chatId = String(msg.chat?.id || from.id || 'tg-chat');
        const userName = [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'Пользователь Telegram';
        const text = String(payload.callback_query?.data || msg.text || payload.text || '');
        return this.handleIncomingMessage({ channel: 'telegram', chatId, userName, text, originOverride });
    }

    /**
     * Разбор нативного Webhook от VK Callback API.
     */
    async handleVkWebhook(payload = {}, originOverride = '') {
        if (payload.type === 'confirmation') {
            return { isVkConfirmation: true, body: this.vkConfirmationCode };
        }
        const obj = payload.object?.message || payload.object || {};
        const chatId = String(obj.peer_id || obj.from_id || payload.chat_id || 'vk-chat');
        const userName = String(payload.user_name || `VK #${obj.from_id || 'user'}`);
        const text = String(obj.text || payload.text || '');
        const result = await this.handleIncomingMessage({ channel: 'vk', chatId, userName, text, originOverride });
        return { isVkConfirmation: false, result, body: 'ok' };
    }

    /**
     * Уведомить все привязанные чаты (MAX, Telegram, VK) об успешной оплате и продлении лицензии.
     */
    async notifyLicenseOrderPaid(order, licenseSummary) {
        const bindings = this.store.getBindingsForLicense(licenseSummary.licenseId);
        const text = [
            `Оплата по заказу ${order.orderId} (${order.amountRub.toLocaleString('ru-RU')} ₽) успешно получена!`,
            `• Лицензия ПАК: ${licenseSummary.licenseId}`,
            `• Доступно одновременных рабочих мест: ${licenseSummary.totalSeats} (${licenseSummary.baseSeats} вечных + ${licenseSummary.addonSeats} годовых)`,
            `• Уровень поддержки: ${licenseSummary.support.tierName} (реакция ${licenseSummary.support.reactionLabel})`,
            `• Доступно обращений: ${licenseSummary.support.ticketsRemaining} из ${licenseSummary.support.ticketsQuota}`,
        ].join('\n');
        for (const b of bindings) {
            await this.sendExternalMessage(b.channel, b.chatId, text);
        }
    }

    /**
     * Доставить ответ инженера поддержки в мессенджер клиента (MAX, Telegram, VK).
     */
    async deliverEngineerReply(ticket) {
        const lastMsg = ticket.messages[ticket.messages.length - 1];
        if (!lastMsg)
            return;
        const text = [
            `Ответ по обращению ${ticket.ticketId} (${lastMsg.author}):`,
            lastMsg.text,
        ].join('\n\n');
        await this.sendExternalMessage(ticket.channel, ticket.chatId, text);
    }

    /**
     * Отправить сообщение во внешний мессенджер (MAX / Telegram / VK) и записать в журнал outboxLog.
     */
    async sendExternalMessage(channel, chatId, text) {
        const entry = {
            channel: String(channel).toLowerCase(),
            chatId: String(chatId),
            text: String(text),
            time: Date.now(),
            deliveredRemote: false,
        };
        this.outboxLog.push(entry);
        if (this.outboxLog.length > 200)
            this.outboxLog.shift();

        if (typeof this.fetchImpl !== 'function')
            return entry;

        try {
            if (entry.channel === 'telegram' && this.telegramBotSecret) {
                const url = `https://api.telegram.org/bot${this.telegramBotSecret}/sendMessage`;
                const res = await this.fetchImpl(url, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ chat_id: entry.chatId, text: entry.text }),
                });
                entry.deliveredRemote = res.ok;
            }
            else if (entry.channel === 'max' && this.maxBotSecret) {
                const url = `https://botapi.max.ru/messages?chat_id=${encodeURIComponent(entry.chatId)}`;
                const res = await this.fetchImpl(url, {
                    method: 'POST',
                    headers: {
                        'Authorization': this.maxBotSecret,
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({ text: entry.text }),
                });
                entry.deliveredRemote = res.ok;
            }
            else if (entry.channel === 'vk' && this.vkBotSecret) {
                const url = 'https://api.vk.com/method/messages.send';
                const params = new URLSearchParams({
                    peer_id: entry.chatId,
                    random_id: String(Math.floor(Math.random() * 1e9)),
                    message: entry.text,
                    v: '5.199',
                    access_token: this.vkBotSecret,
                });
                const res = await this.fetchImpl(`${url}?${params.toString()}`, { method: 'POST' });
                entry.deliveredRemote = res.ok;
            }
        }
        catch { /* в локальном/тестовом режиме остаётся в outboxLog */ }

        return entry;
    }
}

